# White-list version script for libbrotli_shared.z.so
# Upstream internal cross-TU functions are already visibility("hidden")
# (BROTLI_INTERNAL, see c/include/brotli/port.h), so only the public API
# below is exported; everything else is localized at link time.

{
  global:
    /* decoder API (declared in c/include/brotli/decode.h) */
    BrotliDecoderAttachDictionary;
    BrotliDecoderCreateInstance;
    BrotliDecoderDecompress;
    BrotliDecoderDecompressStream;
    BrotliDecoderDestroyInstance;
    BrotliDecoderErrorString;
    BrotliDecoderGetErrorCode;
    BrotliDecoderHasMoreOutput;
    BrotliDecoderIsFinished;
    BrotliDecoderIsUsed;
    BrotliDecoderSetMetadataCallbacks;
    BrotliDecoderSetParameter;
    BrotliDecoderTakeOutput;
    BrotliDecoderVersion;

    /* encoder API (declared in c/include/brotli/encode.h) */
    BrotliEncoderAttachPreparedDictionary;
    BrotliEncoderCompress;
    BrotliEncoderCompressStream;
    BrotliEncoderCreateInstance;
    BrotliEncoderDestroyInstance;
    BrotliEncoderDestroyPreparedDictionary;
    BrotliEncoderHasMoreOutput;
    BrotliEncoderIsFinished;
    BrotliEncoderMaxCompressedSize;
    BrotliEncoderPrepareDictionary;
    BrotliEncoderSetParameter;
    BrotliEncoderTakeOutput;
    BrotliEncoderVersion;
    /* reserved: ENC_EXTRA API, declared in encode.h but currently built as
       internal (BROTLI_BUILD_ENC_EXTRA_API not defined); listed here so a
       future upstream sync does not silently drop them */
    BrotliEncoderEstimatePeakMemoryUsage;
    BrotliEncoderGetPreparedDictionarySize;

    /* shared dictionary API (declared in c/include/brotli/shared_dictionary.h) */
    BrotliSharedDictionaryAttach;
    BrotliSharedDictionaryCreateInstance;
    BrotliSharedDictionaryDestroyInstance;

    /* common API (upstream BROTLI_COMMON_API, declared in c/common/*.h,
       used for allocator hooks and C/Java dictionary sharing) */
    BrotliDefaultAllocFunc;
    BrotliDefaultFreeFunc;
    BrotliGetDictionary;
    BrotliGetTransforms;
    BrotliSetDictionaryData;
    BrotliTransformDictionaryWord;
  local:
    *;
};
